#!/usr/bin/env bash
# SPDX-FileCopyrightText: 2026 IObundle
#
# SPDX-License-Identifier: GPL-3.0-only

# Generate the Verilog of one py2hwsw core as of one commit.
#
# Usage: .github/formal/generate_core.sh <core> <commit> <output-dir>
#
# The core is set up with the py2hwsw of <commit> itself (a git worktree), so
# the framework and the generated submodules (iob_reg, ...) come from the same
# commit. The sources end up in <output-dir>/build/hardware/src.

set -euo pipefail

if [ $# -ne 3 ]; then
    sed -n '7,13p' "$0"
    exit 64
fi

core=$1
rev=$2
out=$(mkdir -p "$3" && cd "$3" && pwd)
repo=$(git rev-parse --show-toplevel)
python=${PYTHON:-python3}
tree=${RUNNER_TEMP:-/tmp}/py2hwsw-formal/$(git rev-parse --short "$rev")

# py2hwsw setup formats the generated Verilog with verible-verilog-format.
# Formatting does not change the RTL, so without verible a no-op is used.
if ! command -v verible-verilog-format >/dev/null 2>&1; then
    shim=${RUNNER_TEMP:-/tmp}/py2hwsw-formal/bin
    mkdir -p "$shim"
    printf '#!/bin/sh\nexit 0\n' >"$shim/verible-verilog-format"
    chmod +x "$shim/verible-verilog-format"
    export PATH="$shim:$PATH"
fi

if [ ! -d "$tree" ]; then
    git -C "$repo" worktree add --detach "$tree" "$rev" >/dev/null
fi

# py2hwsw also looks up cores under the current directory, so setup runs from
# a directory that holds only this side's build output.
rm -rf "$out/build"
(cd "$out" && "$python" "$tree/py2hwsw/scripts/py2hwsw.py" "$core" setup \
    --build_dir "$out/build" --no_verilog_lint) >"$out/setup.log" 2>&1 || {
    tail -20 "$out/setup.log"
    echo "py2hwsw setup of $core at $rev failed" >&2
    exit 1
}

src=$out/build/hardware/src
# iob_bsp.vh is a board header generated by the parent SoC. Library registers
# include it without using its macros; an empty one is added to both sides.
if [ ! -f "$src/iob_bsp.vh" ]; then
    echo "// empty board header (normally generated by the parent SoC)" >"$src/iob_bsp.vh"
fi
ls "$src"/*.v >/dev/null
echo "$core at $(git rev-parse --short "$rev"): $(ls "$src" | wc -l | tr -d ' ') files in $src"
